plugins {
    alias(libs.plugins.android.library)
}

// Prebuilt PJSIP/PJSUA2: libpjsua2.so + libc++_shared.so per ABI and the SWIG Java bindings
// (org.pjsip.pjsua2). Generated by scripts/build-pjsip.sh — see BUILD_INFO for pinned versions.
android {
    namespace = "org.pjsip.pjsua2.android"
    compileSdk {
        version = release(37)
    }
    defaultConfig {
        minSdk = 26
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    lint {
        // Generated SWIG code; findings here are not actionable.
        checkReleaseBuilds = false
        ignoreWarnings = true
    }
}

tasks.named("preBuild") {
    val jniLibs = file("src/main/jniLibs") // capture a plain File only (configuration cache)
    doFirst {
        check(jniLibs.isDirectory) {
            "PJSIP binaries are missing. Run sip/pjsip-native/scripts/build-pjsip.sh (Linux/WSL)."
        }
    }
}
